/* @lc app=leetcode id=3934 lang=kotlin */ class Solution { fun smallestUniqueSubarray(nums: IntArray): Int = nums.size.let { n -> longArrayOf(1_000_000_007L, 998_244_353L).let { md -> longArrayOf(100_003L, 100_019L).let { bs -> Array(2) { k -> nums.runningFold(0L) { a, x -> (a * bs[k] + x) % md[k] }.toLongArray() }.let { h -> Array(2) { k -> generateSequence(1L) { it * bs[k] % md[k] }.take(n + 1).toList().toLongArray() }.let { pw -> generateSequence(1 to n) { (lo, hi) -> if (lo >= hi) null else ((lo + hi) / 2).let { L -> if ((0..n - L).map { i -> (((h[0][i + L] - h[0][i] * pw[0][L]) % md[0] + md[0]) % md[0] shl 32) or (((h[1][i + L] - h[1][i] * pw[1][L]) % md[1] + md[1]) % md[1]) }.groupingBy { it }.eachCount().values.any { it == 1 }) lo to L else L + 1 to hi } }.last().first } } } } } }